"""Generate the checked-in snapshot report from verified catalog artifacts."""

import argparse
import json
from collections import Counter
from pathlib import Path


def render(packed, facets, changelog, harvest=None):
    rows = packed['rows']
    total = len(rows)
    if facets['total'] != total:
        raise ValueError('Facet total does not match the packed catalog')
    activity = Counter(entry[0] for entry in packed['activity'])
    topics = sum(bool(row[13]) for row in rows if len(row) > 13)
    lines = [
        '# Catalog snapshot', '',
        '<!-- Generated by pipeline/catalog_summary.py. -->', '',
        f"Snapshot: **{changelog['generated']}**. "
        'Counts below describe the checked-in catalog, not a live GitHub counter.', '',
        '| Metric | Count |', '| --- | ---: |',
        f'| Repositories | {total:,} |',
        f'| Minimum stars observed | {min(row[3] for row in rows):,} |',
        f'| Domains | {len(packed["domains"]):,} |',
        f'| Primary-language buckets | {len(packed["languages"]):,} |',
        f'| Repositories with topics | {topics:,} ({100 * topics / total:.1f}%) |',
        f'| Active / idle / archived / unknown | {activity["active"]:,} / '
        f'{activity["idle"]:,} / {activity["archived"]:,} / {activity[None]:,} |',
    ]
    if changelog['period']:
        period = changelog['period']
        lines += ['', f"### Changes since {period['from']}", '',
                  f"- Added **{changelog['added_count']:,}** catalog entries; "
                  f"removed **{changelog['removed_count']:,}**.",
                  f"- **{changelog['mover_count']:,}** existing entries changed star count.",
                  '- [Changelog data](../web/public/changelog.json) includes all additions and '
                  'removals. Additions include older projects newly found by the sweep, not just '
                  'repositories created during this period.']
    else:
        lines += ['', 'This is the baseline; there is no earlier snapshot to compare.']
    if harvest:
        lines += ['', '### GitHub Search coverage', '',
                  f"- Completed **{harvest['windows_done']:,}/{harvest['windows_planned']:,}** windows "
                  f"({harvest['windows_failed']:,} failed; {harvest['windows_truncated']:,} truncated).",
                  f"- **{harvest['unique_repositories']:,}** distinct names returned before reconciliation; "
                  f"planning probes estimated **{harvest['universe_estimate']:,}**.",
                  '- GitHub Search changes during a sweep. Previously cataloged names missing from '
                  'search are checked separately against the repository API.']
    lines += ['', '### Domains', '', '| Domain | Repositories |', '| --- | ---: |']
    lines.extend(f"| {x['name']} | {x['count']:,} |" for x in facets['domains'])
    return '\n'.join(lines) + '\n'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--base-dir', type=Path, default=Path('web/public'))
    parser.add_argument('--output', type=Path, default=Path('docs/CATALOG_SNAPSHOT.md'))
    parser.add_argument('--harvest-stats', type=Path)
    args = parser.parse_args()
    docs = [json.loads((args.base_dir / name).read_text(encoding='utf-8'))
            for name in ('catalog-packed.json', 'facets.json', 'changelog.json')]
    harvest = json.loads(args.harvest_stats.read_text(encoding='utf-8')) if args.harvest_stats else None
    args.output.write_text(render(*docs, harvest), encoding='utf-8')


if __name__ == '__main__':
    main()
